.git
target/
blank_issues_enabled: true
{
  "name": "Rustix",
  "build": {
    "dockerfile": "Dockerfile",
    "context": ".."
  },
  "features": {
    "ghcr.io/devcontainers/features/rust:1": {
      "version": "stable",
      "profile": "minimal",
      "components": "rustfmt",
      "targets": "x86_64-unknown-none"
    }
  },
  "customizations": {
    "vscode": {
      "extensions": [
        "rust-lang.rust-analyzer"
      ]
    }
  },
  "remoteUser": "vscode"
}
{
  "hooks": {
    "PreToolUse": [
      {
        "hooks": [
          {
            "command": "cmd /c \"entire-brain hook pre-edit --claude-hook || entire brain hook pre-edit --claude-hook || exit /b 0\"",
            "type": "command"
          }
        ],
        "matcher": "Edit|Write|MultiEdit|NotebookEdit"
      }
    ]
  }
}
{
  "hooks": {
    "SubagentStart": [
      {
        "hooks": [
          {
            "command": "try { & entire graph hook claude-subagent-start 2>$null } catch {}; exit 0",
            "shell": "powershell",
            "timeout": 10,
            "type": "command"
          }
        ],
        "matcher": "*"
      }
    ]
  }
}
{
  "enabled": true,
  "telemetry": true,
  "checkpoints": {
    "primary": {
      "type": "git-refs"
    }
  }
}
{
  "external_agents": true
}

